    "question": "Q353. (NEET Medium) According to Crystal Field Theory (CFT), for an octahedral complex with $d^4$ configuration, pairing of electrons will occur to give a low-spin state ($t_{2g}^4 e_g^0$) when:",
    "options": {
      "A": "$\\Delta_o > P$ (crystal field splitting exceeds electron pairing energy)",
      "B": "$\\Delta_o < P$",
      "C": "$\\Delta_o = 0$",
      "D": "$\\Delta_t = \\frac{4}{9} \\Delta_o$"
    },
